CREATE TABLE draws (id TEXT PRIMARY KEY, activity_id TEXT NOT NULL, owner_id TEXT NOT NULL, request_key TEXT NOT NULL, rule_version INTEGER NOT NULL CHECK(rule_version=1), winner_id TEXT NOT NULL, winner_ordinal INTEGER NOT NULL, created_at INTEGER NOT NULL, UNIQUE(activity_id,request_key), UNIQUE(activity_id,winner_id), FOREIGN KEY(activity_id,owner_id) REFERENCES activities(id,owner_id));
CREATE TABLE draw_candidates (draw_id TEXT NOT NULL REFERENCES draws(id), viewer_id TEXT NOT NULL, ordinal INTEGER NOT NULL, score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 10), weight REAL NOT NULL, probability REAL NOT NULL, PRIMARY KEY(draw_id,viewer_id));
